contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public {
        uint256 lenBefore = 0;
        while (true) {
            try c.rewardTokens(lenBefore) returns (address) {
                lenBefore++;
            } catch {
                break;
            }
        }

        (, , uint40 lastUpdateTimeBefore, ) = c.rewardData(token);

        bool revertedBefore = false;
        try c.addReward(token) {
            revertedBefore = false;
        } catch {
            revertedBefore = true;
        }

        uint256 lenAfter = 0;
        while (true) {
            try c.rewardTokens(lenAfter) returns (address) {
                lenAfter++;
            } catch {
                break;
            }
        }

        (, , uint40 lastUpdateTimeAfter, ) = c.rewardData(token);

        bool expectedSuccess = (lastUpdateTimeBefore == 0);
        bool observedSuccess = !revertedBefore;

        bool lenGrewByOne = (lenAfter == lenBefore + 1);
        bool lenUnchanged = (lenAfter == lenBefore);

        bool lastTimeSet = (lastUpdateTimeAfter != 0);
        bool lastTimeUnchanged = (lastUpdateTimeAfter == lastUpdateTimeBefore);

        bool appended = false;
        if (lenAfter > 0) {
            appended = (c.rewardTokens(lenAfter - 1) == token);
        }

        assert(
            (expectedSuccess == observedSuccess) &&
            (expectedSuccess ? (lastTimeSet && lenGrewByOne && appended) : (lastTimeUnchanged && lenUnchanged))
        );
    }

    receive() external payable {}
}

