    function run(uint256 amount) public {
        require(amount > 0, "need positive amount");

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        // Give this test contract enough tokens and approve c to pull them.
        IERC20 staking = c.stakingToken();
        staking.transfer(address(this), amount);
        staking.approve(address(c), amount);

        // Assume the precondition holds: this test has the tokens and approval.
        require(staking.balanceOf(address(this)) >= amount);
        require(staking.allowance(address(this), address(c)) >= amount);

        bool reverted;
        try c.stakeFor(address(this), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balanceOf(address(this));
        uint256 totalAfter = c.totalSupply();

        if (!reverted) {
            assert(balanceAfter == balanceBefore + amount);
            assert(totalAfter == totalBefore + amount);
        }

        // A positive stake with balance and approval must not revert.
        assert(!reverted);
    }

    receive() external payable {}
}

