contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount, address caller, uint256 stakeAmount) public payable {
        require(staker != address(0), "zero staker");
        require(caller != address(0), "zero caller");

        // Setup: make caller the migrator by sending the onlyOwner call.
        // The test contract is the owner from the constructor, so it can set migrator.
        c.setMigrator(caller);

        // Give staker a balance in c using a fresh third-party account with tokens.
        // We only control c, so we cannot mint tokens. However, we can drive
        // staking by transferring tokens from this contract's balance if it has, or skip
        // if no tokens. To keep the test self-contained, we read c.balanceOf(staker)
        // after attempting to withdraw; the revert condition only depends on the actor.
        uint256 balBefore = c.balanceOf(staker);
        bool reverted;
        try c.migrateWithdraw(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter = c.balanceOf(staker);
        uint256 totalAfter = c.totalSupply();

        if (!reverted) {
            // If it did not revert, caller must be the migrator and the staker must
            // have had at least `amount` staked.
            assert(caller == c.migrator());
            assert(balBefore >= amount);
            assert(balAfter == balBefore - amount);
            assert(totalAfter == c.totalSupply());
        } else {
            // If it reverted, either the caller was not the migrator or the staker
            // had insufficient balance.
            assert(caller != c.migrator() || balBefore < amount);
        }
    }
}

