contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address migratorAddr, uint256 amount, address staker) public payable {
        require(migratorAddr != address(0), "migrator must be nonzero");
        require(amount > 0, "amount must be positive");
        require(staker != address(0), "staker must be nonzero");

        // Record the observable pre-state of c.
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(staker);

        // Configure c so migratorAddr is the authorized migrator.
        c.setMigrator(migratorAddr);

        // Drive migrateStake from the test contract; since msg.sender is not
        // migratorAddr (unless migratorAddr == address(this)), a revert is expected.
        bool reverted;
        try c.migrateStake(address(c), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: migrateStake must revert whenever called by a non-migrator.
        // The expected states are the same regardless of whether the caller is the
        // migrator (in which case some state may change), so we only assert the
        // revert condition for the case we can safely observe without needing an
        // old staking contract to act as msg.sender inside migrateStake.
        if (migratorAddr != address(this)) {
            assert(reverted && c.totalSupply() == supplyBefore && c.balanceOf(staker) == balBefore);
        } else {
            // The test contract itself is the migrator; in this branch the call may
            // succeed or revert, but the rule is not asserted here.
            assert(true);
        }
    }

    receive() external payable {}
}

