contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, address rewardToken) public {
        // Setup: add rewardToken so rewardData[rewardToken].lastUpdateTime != 0.
        // Only the owner (this contract, which deployed c) can call addReward.
        c.addReward(rewardToken);

        // Read the public mapping directly for the current claimable amount.
        uint256 claimable = c.claimableRewards(account, rewardToken);

        // Call the public view function. This is a read-only call and can be used to
        // observe the return value, but we must not nest it inside require/assert for
        // state-changing calls; earned is view, so it's allowed.
        uint256 earned = c.earned(account, rewardToken);

        // General rule: immediately after setup (lastUpdateTime = now), the earned
        // amount computed from the current stored rewardPerTokenStored and
        // userRewardPerTokenPaid equals the claimableRewards mapping entry.
        // This holds because:
        //   earned = balance * (_rewardPerToken() - userRewardPerTokenPaid) / 1e18 + claimableRewards
        // and _rewardPerToken() returns rewardPerTokenStored when totalSupply == 0
        // or lastUpdateTime == block.timestamp. In either case, the delta should be zero
        // for an account that has never staked or updated, so earned == claimableRewards.
        // More robustly, for any state right after addReward (fresh reward token),
        // userRewardPerTokenPaid is 0 and claimableRewards is whatever was there.
        // The key invariant: earned(account, token) >= claimable(account, token) is always true,
        // but since we want a general rule that would break on faulty versions, we assert
        // that the returned value is exactly the claimable mapping when the reward token
        // was just added and the account has no prior stake interaction.
        // We use the fact that addReward sets lastUpdateTime = block.timestamp, so any
        // _rewardPerToken computation for the first block should yield rewardPerTokenStored
        // exactly, making the balance term zero if userRewardPerTokenPaid is 0.
        // However, balanceOf(account) may be nonzero from a previous stake in the same tx?
        // No: this is the first call, and we haven't staked. So balanceOf(account) is 0.
        // Therefore earned = 0 + claimableRewards[account][token].
        assert(earned == claimable);
    }

    receive() external payable {}
}

