contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address forAddr, address payer, uint256 amount) public payable {
        // Setup: register a reward token so reward bookkeeping is exercised.
        // This call must succeed regardless of inputs.
        c.addReward(address(0xdead));
        require(amount > 0, "need nonzero amount for this proof");

        uint256 supplyBefore = c.totalSupply();
        uint256 balForBefore = c.balanceOf(forAddr);

        uint256 balContractBefore = c.stakingToken().balanceOf(address(c));
        uint256 balPayerBefore = c.stakingToken().balanceOf(payer);

        bool reverted;
        try c.stakeFor(forAddr, amount) { reverted = false; }
        catch { reverted = true; }

        uint256 supplyAfter = c.totalSupply();
        uint256 balForAfter = c.balanceOf(forAddr);
        uint256 balContractAfter = c.stakingToken().balanceOf(address(c));
        uint256 balPayerAfter = c.stakingToken().balanceOf(payer);

        if (reverted) {
            // A failed stake must not change any tracked state or move tokens.
            assert(
                supplyAfter == supplyBefore &&
                balForAfter == balForBefore &&
                balContractAfter == balContractBefore &&
                balPayerAfter == balPayerBefore
            );
        } else {
            // A successful stake pulls the tokens from the payer and mints
            // internal stake exactly 1:1 to the recipient.
            assert(
                supplyAfter == supplyBefore + amount &&
                balForAfter == balForBefore + amount &&
                balContractAfter == balContractBefore + amount &&
                balPayerAfter == balPayerBefore - amount
            );
        }
    }
    receive() external payable {}
}

