        uint256 len = getRewardTokensLength();
        require(len > 0, "need a reward token");
        uint256 idx = i % len;
        address token = c.rewardTokens(idx);

        uint256 direct = c.rewardPerToken(token);
        (bool ok, bytes memory data) = address(c).staticcall(
            abi.encodeWithSignature("rewardPerToken(address)", token)
        );
        require(ok, "query must succeed");
        uint256 viaCall = abi.decode(data, (uint256));

        assert(viaCall == direct);
    }

    function getRewardTokensLength() internal view returns (uint256) {
        uint256 len = 0;
        while (true) {
            (bool ok, bytes memory data) = address(c).staticcall(
                abi.encodeWithSignature("rewardTokens(uint256)", len)
            );
            if (!ok) break;
            len++;
        }
        return len;
    }
}

