    constructor(C _c) { c = _c; }

    function run(address account, address rewardToken, uint256 stakeAmount) public payable {
        require(account != address(0), "account zero");
        require(rewardToken != address(0), "token zero");
        require(stakeAmount > 0, "stake zero");

        // Read-only observation of current reward token state for rewardToken.
        uint40 lastUpdateTimeBefore = c.rewardData(rewardToken).lastUpdateTime;
        uint40 periodFinishBefore = c.rewardData(rewardToken).periodFinish;

        // earned() is a view; drive it and capture the returned value.
        uint256 earnedBefore = c.earned(account, rewardToken);

        // earned() must not alter c's public reward-token bookkeeping for this token
        // (checked by comparing the getter after the call, in one expression).
        bytes32 rewardDataAfterHash = keccak256(abi.encode(c.rewardData(rewardToken)));
        bytes32 rewardDataBeforeHash = keccak256(
            abi.encode(
                c.rewardData(rewardToken).periodFinish,
                c.rewardData(rewardToken).rewardRate,
                c.rewardData(rewardToken).lastUpdateTime,
                c.rewardData(rewardToken).rewardPerTokenStored
            )
        );

        assert(
            earnedBefore == c.earned(account, rewardToken) &&
            rewardDataAfterHash == rewardDataBeforeHash &&
            c.rewardData(rewardToken).lastUpdateTime == lastUpdateTimeBefore &&
            c.rewardData(rewardToken).periodFinish == periodFinishBefore
        );
    }

    receive() external payable {}
}

