contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address stakingToken, address staker, address spender, uint256 amount, uint256 preBalance) public {
        // We drive c through its public entry `stakeFor`.
        // Precondition on parameter used as the staking-token address.
        require(stakingToken != address(0));
        require(staker != address(0));
        require(spender != address(0));

        // Set up the state the rule needs, using only public entry points of c.
        c.addReward(stakingToken);
        c.setMigrator(spender);

        // Read before-values of the staker's stake and of the contract's total supply.
        uint256 beforeBalance = c.balanceOf(staker);
        uint256 beforeTotal = c.totalSupply();

        // Make the deciding call on the public entry `stakeFor`
        // (no require() on c's private state before the call that creates it).
        bool reverted;
        try c.stakeFor(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 afterBalance, uint256 afterTotal) = (c.balanceOf(staker), c.totalSupply());

        // General rule: when `amount` is positive, `stakeFor` succeeds (does not revert)
        // iff the staker's balance and the total supply both increase by `amount`.
        // The if/else form avoids subtraction that could underflow inside the assert.
        if (reverted) {
            assert(amount == 0 || afterBalance != beforeBalance + amount || afterTotal != beforeTotal + amount);
        } else {
            assert(afterBalance == beforeBalance + amount && afterTotal == beforeTotal + amount);
        }
    }

    receive() external payable {}
}

