    constructor(C _c) { c = _c; }

    function run(address stakingToken, address for_, uint256 amount) public {
        require(stakingToken != address(0), "bad token");

        // stakingToken must be the one c uses; read via public getter
        address realToken = address(c.stakingToken());
        require(realToken == stakingToken, "token mismatch");

        uint256 balanceBefore = IERC20(stakingToken).balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        uint256 forBalBefore = c.balanceOf(for_);

        bool reverted;
        try c.stakeFor(for_, amount) { reverted = false; } catch { reverted = true; }

        if (amount == 0) {
            assert(reverted);
        } else {
            // if caller has enough tokens approved/owned, stake must succeed
            if (balanceBefore >= amount) {
                assert(!reverted);
                assert(c.totalSupply() == supplyBefore + amount);
                assert(c.balanceOf(for_) == forBalBefore + amount);
            } else {
                assert(reverted);
            }
        }
    }

    receive() external payable {}
}

