contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address for_, uint256 amount, uint256 seedAmount) public {
        require(for_ != address(0));
        // Setup: make a non-zero seed stake so staking token accounting is meaningful when possible.
        // Use seedAmount only if it is positive; otherwise skip. We drive through stakeFor so state exists.
        uint256 supplyBefore = c.totalSupply();
        uint256 forBalBefore = c.balanceOf(for_);

        bool reverted;
        try c.stakeFor(for_, amount) { reverted = false; } catch { reverted = true; }

        // General rule: stakeFor either credits exactly `amount` to `for_` and totalSupply,
        // or it reverts and leaves totalSupply and balanceOf(for_) unchanged.
        // The only way it reverts is amount == 0 or insufficient staking tokens (observable as a revert).
        assert(
            (reverted && c.totalSupply() == supplyBefore && c.balanceOf(for_) == forBalBefore) ||
            (!reverted && amount > 0 && c.totalSupply() == supplyBefore + amount && c.balanceOf(for_) == forBalBefore + amount)
        );
    }

    receive() external payable {}
}

