contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, address staker, uint256 stakeAmount) public {
        require(rewardToken != address(0));
        require(staker != address(0));
        require(stakeAmount > 0);

        c.addReward(rewardToken);

        uint256 before = c.rewardPerToken(rewardToken);

        // Drive the public entry point rewardPerToken again after a state change
        // (a stake increases totalSupply, which cannot decrease accrued rewards).
        uint256 tokenBal = c.stakingToken().balanceOf(address(this));
        if (tokenBal >= stakeAmount) {
            c.stakingToken().approve(address(c), stakeAmount);
            c.stakeFor(staker, stakeAmount);
        }

        uint256 afterVal = c.rewardPerToken(rewardToken);

        assert(afterVal >= before);
    }
}
